    # These boards consist of repeated reflected 16x16 patch patterns.
    # For a masked cell, use the closest position with equal coordinates
    # modulo 16; resolve ties by agreeing values.
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 6:
                continue
            votes = {}
