        # Tile alignment is 16; use same relative tile coordinate if visible.
        for rr, cc in ((r%16,c%16), (r%16, 31-(c%16)),
                       (31-(r%16),c%16), (31-(r%16),31-(c%16))):
            if rr < h and cc < w and grid[rr][cc] != 6:
